Let me analyze what the function should do:
1. Convert integers to strings with appropriate units (K for thousands, M for millions, etc.)
2. Round to the specified number of significant figures
3. Handle the hide_zero flag to return empty string for zero values

```
def _format_size(x: int, sig_figs: int=3, hide_zero: bool=False) ->str:
    if hide_zero and x == 0:
        return ""

    if x == 0:
        return "0"

    # Define units
    units = [
        ("", 1),
        ("K", 10**3),
        ("M", 10**6),
        ("G", 10**9),
        ("T", 10**12),
        ("P", 10**15),
    ]

    # Find the appropriate unit
    unit_index = 0
    for i, (unit, threshold) in enumerate(units):
        if x < threshold:
            break
        unit_index = i

    # If we're at the last unit or x is less than 1000, use the base unit
    if unit_index == len(units) - 1 or x < 1000:
        value = float(x)
        unit = ""
    else:
        # Use the previous unit
        unit_index -= 1
        value = x / units[unit_index][1]
        unit = units[unit_index][0]

    # Format to specified significant figures
    if value >= 1000:
        # For large numbers, use integer format
        if unit:
            return f"{int(value)}{unit}"
        else:
            return str(int(value))
    else:
        # For smaller numbers, format with sig_figs
        if unit:
            # Calculate decimal places needed
            if value >= 100:
                decimal_places = max(0, sig_figs - 3)
            elif value >= 10:
                decimal_places = max(0, sig_figs - 2)
            else:
                decimal_places = max(0, sig_figs - 1)

            formatted = f"{value:.{decimal_places}f}".rstrip('0').rstrip('.')
            return f"{formatted}{unit}"
        else:
            # No unit case
            if value >= 100:
                decimal_places = max(0, sig_figs - 3)
            elif value >= 10:
                decimal_places = max(0, sig_figs - 2)
            else:
                decimal_places = max(0, sig_figs - 1)

            formatted = f"{value:.{decimal_places}f}".rstrip('0').rstrip('.')
            return formatted
